-- VIPER AI: Race Day Command Centre and private rider availability
-- Run once against the VIPER AI Supabase project.
create table if not exists public.race_day_checklist (
 id bigint generated by default as identity primary key,
 race_day_id bigint not null references public.race_days(id) on delete cascade,
 item text not null check(length(trim(item))>0), is_done boolean not null default false,
 notes text, created_by uuid references auth.users(id) on delete set null,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index if not exists race_day_checklist_day_idx on public.race_day_checklist(race_day_id,created_at);
alter table public.race_day_checklist enable row level security;
drop policy if exists "approved leadership reads race checklist" on public.race_day_checklist;
drop policy if exists "approved leadership inserts race checklist" on public.race_day_checklist;
drop policy if exists "approved leadership updates race checklist" on public.race_day_checklist;
drop policy if exists "approved leadership deletes race checklist" on public.race_day_checklist;
create policy "approved leadership reads race checklist" on public.race_day_checklist for select to authenticated using (exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.status='approved' and p.role in ('captain','leadership')));
create policy "approved leadership inserts race checklist" on public.race_day_checklist for insert to authenticated with check (created_by=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.status='approved' and p.role in ('captain','leadership')));
create policy "approved leadership updates race checklist" on public.race_day_checklist for update to authenticated using (exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.status='approved' and p.role in ('captain','leadership'))) with check (exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.status='approved' and p.role in ('captain','leadership')));
create policy "approved leadership deletes race checklist" on public.race_day_checklist for delete to authenticated using (exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.status='approved' and p.role in ('captain','leadership')));

create table if not exists public.race_day_updates (
 id bigint generated by default as identity primary key,
 race_day_id bigint not null references public.race_days(id) on delete cascade,
 message text not null check(length(trim(message))>0),
 category text not null default 'Update' check(category in ('Update','Schedule','Safety','Result')),
 created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now()
);
create index if not exists race_day_updates_day_idx on public.race_day_updates(race_day_id,created_at desc);
alter table public.race_day_updates enable row level security;
drop policy if exists "approved members read race day updates" on public.race_day_updates;
drop policy if exists "leadership inserts race day updates" on public.race_day_updates;
drop policy if exists "leadership deletes race day updates" on public.race_day_updates;
create policy "approved members read race day updates" on public.race_day_updates for select to authenticated using (is_approved());
create policy "leadership inserts race day updates" on public.race_day_updates for insert to authenticated with check (created_by=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.status='approved' and p.role in ('captain','leadership')));
create policy "leadership deletes race day updates" on public.race_day_updates for delete to authenticated using (exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.status='approved' and p.role in ('captain','leadership')));

create table if not exists public.rider_availability (
 id bigint generated by default as identity primary key, rider_name text not null unique check(length(trim(rider_name))>0),
 availability text not null default 'unknown' check(availability in ('available','limited','unavailable','unknown')),
 injury_status text not null default 'not_reported' check(injury_status in ('not_reported','fit','restricted','unavailable','recovering')),
 event_id bigint references public.race_days(id) on delete set null, expected_return date, private_notes text,
 updated_by uuid references auth.users(id) on delete set null, updated_at timestamptz not null default now()
);
create index if not exists rider_availability_event_idx on public.rider_availability(event_id);
alter table public.rider_availability enable row level security;
drop policy if exists "leadership reads rider availability" on public.rider_availability;
drop policy if exists "leadership inserts rider availability" on public.rider_availability;
drop policy if exists "leadership updates rider availability" on public.rider_availability;
drop policy if exists "leadership deletes rider availability" on public.rider_availability;
create policy "leadership reads rider availability" on public.rider_availability for select to authenticated using (exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.status='approved' and p.role in ('captain','leadership')));
create policy "leadership inserts rider availability" on public.rider_availability for insert to authenticated with check (updated_by=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.status='approved' and p.role in ('captain','leadership')));
create policy "leadership updates rider availability" on public.rider_availability for update to authenticated using (exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.status='approved' and p.role in ('captain','leadership'))) with check (updated_by=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.status='approved' and p.role in ('captain','leadership')));
create policy "leadership deletes rider availability" on public.rider_availability for delete to authenticated using (exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.status='approved' and p.role in ('captain','leadership')));

-- Let approved leadership add race result rows; existing read and captain-write policies remain intact.
drop policy if exists "approved leadership inserts race results" on public.race_records;
create policy "approved leadership inserts race results" on public.race_records for insert to authenticated with check (exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.status='approved' and p.role in ('captain','leadership')));
